            formalityVariants: {
              casual: "Yeah, I could use some fresh air too. And hey, if you're still stuck after that, I can take a look at your code. Sometimes a fresh pair of eyes helps.",
              standard: "Sure, I could use some fresh air too. And hey, if you are still stuck after that, I can take a look at your code. Sometimes a fresh pair of eyes helps.",
              formal: "Certainly, I would also appreciate some fresh air. Furthermore, if you continue to encounter difficulties thereafter, I would be happy to review your code. A new perspective often proves beneficial.",
            },
