            formalityVariants: {
              casual: "That's awesome. What were the biggest headaches during setup?",
              standard: "That is fascinating. I would love to hear more about your experience with it. What were the biggest challenges you faced during implementation?",
              formal: "How fascinating. I would be very interested to learn more about your experience. Could you share the most significant challenges you encountered during the implementation process?",
            },
